async function showWhatsApp(guest,invitationLink=null){
 const g=db.guests.find(x=>x.id===guest.id);if(!g?.active)return toast('Aktifkan undangan sebelum membagikannya.');
 if(!g.phone){editGuest(g);return toast('Isi nomor WhatsApp, simpan, lalu pilih WhatsApp kembali.');}
 try{invitationLink=invitationLink||await guestInvitationURL(g);}catch(error){toast(error.message);return;}
 const event=structuredClone(db.event),code=g.code,phone=g.phone;
 const publicLink=invitationLink;
 const draft=TemuInvitations.message(g,event)+'\n\nLihat undangan digital kami:\n'+publicLink;
 modal('Undangan untuk '+g.name,`<p>WhatsApp tujuan: <strong>+${esc(phone)}</strong></p><div class="qr-preview">${qrSVG(g)}</div><label for="whatsapp-text">Teks undangan</label><textarea id="whatsapp-text" rows="8" maxlength="4000">${esc(draft)}</textarea><p id="share-info" class="hint" role="status">Menyiapkan satu gambar QR…</p><div class="actions"><button id="download-png" class="primary" disabled>1. Unduh QR PNG</button><button id="open-whatsapp">2. Buka WhatsApp dengan teks</button><button id="copy-invite">Salin teks saja</button></div><p class="hint">Lampirkan PNG yang diunduh <strong>sekali</strong> pada chat WhatsApp. Teks sudah terisi saat chat dibuka; periksa penerima dan isi pesan sebelum mengirim.</p>`);
 const box=$('#whatsapp-text'),downloadButton=$('#download-png'),info=$('#share-info');
 const current=()=>{const latest=db.guests.find(x=>x.id===g.id);if(db.event.id!==event.id||!latest?.active||latest.code!==code||latest.phone!==phone||JSON.stringify(latest)!==JSON.stringify(g)||JSON.stringify(db.event)!==JSON.stringify(event))throw Error('Undangan berubah. Tutup dan buka kembali sebelum mengirim.');if(!box.value.trim())throw Error('Isi teks undangan terlebih dahulu.');return box.value;};
 $('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(current());toast('Teks disalin. Tempelkan pada pesan WhatsApp.');}catch(e){box.focus();box.select();toast('Pilih dan salin teks undangan secara manual.');}};
 $('#open-whatsapp').onclick=()=>{try{const url=TemuInvitations.whatsappURL(phone,current());window.open(url,'_blank','noopener,noreferrer');info.textContent='Chat WhatsApp dibuka dengan teks tanpa path file. Lampirkan QR PNG satu kali sebelum mengirim.';}catch(e){toast(e.message);}};
 try{
 const file=await TemuInvitations.qrFile(g,event);if($('#download-png')!==downloadButton)return;
 downloadButton.disabled=false;downloadButton.onclick=()=>{try{current();download(file,file.name,'image/png');info.textContent='QR PNG diunduh. Buka WhatsApp dengan teks, lalu lampirkan gambar ini satu kali.';}catch(e){toast(e.message);}};
 info.textContent='QR siap. Unduh gambarnya, kemudian buka WhatsApp dengan teks undangan.';
 }catch(e){if($('#share-info')===info)info.textContent=e.message+' Tutup dan coba lagi.';}
}
